# Own-wording feats of Dark Matter (2024 rules), Mage Hand Press. Part B: Iron Hero to Warzone Nomad. Shapes follow tvss_feat.py and tee24_feat.py.
ALSO = []
FEATS = {
 "Iron Hero": {"d": "+2 AC against attackers with CR above your level. Advantage against foes that downed an ally. Reaction to stop a Legendary Action, Proficiency Bonus times per Long Rest.", "pre": "Level 4+", "asi": ["STR", "DEX"],
   "full": "Raise Strength or Dexterity by 1, to a maximum of 20.\n**Underdog's Resolve.** When a creature whose CR is higher than your level attacks you, you gain a +2 bonus to AC against that attack.\n**Vengeful Strike.** You have Advantage on attack rolls against a creature that has dropped one of your allies to 0 Hit Points since the end of your last turn.\n**Heroic Intervention.** When an enemy you can see takes a Legendary Action, you can use your Reaction to step in and stop that action from happening. You can do this a number of times equal to your Proficiency Bonus and regain all uses on a Long Rest.",
   "lu": {"n": "Heroic Intervention", "max": "pb", "reset": "long", "tag": "Reaction"}, "act": "reaction"},
 "Ironwood Dryad": {"d": "Without armor, AC is 15 (a Shield is allowed). Magic action: spend a Hit Die to heal, Proficiency Bonus times per Long Rest.", "pre": "Elf",
   "full": "**Barkflesh.** While you wear no armor, your AC is 15. You can carry a Shield and keep this benefit.\n**Natural Regeneration.** As a Magic action you can mend your wooden flesh. Spend one Hit Point Die, roll it, and regain Hit Points equal to the roll plus your Constitution modifier. You can do this a number of times equal to your Proficiency Bonus and regain all uses on a Long Rest.",
   "lu": {"n": "Natural Regeneration", "max": "pb", "reset": "long", "tag": "Magic action"},
   "fx": {"notes": [["Note", "Barkflesh: AC 15 with no armor, a Shield is allowed (Ironwood Dryad)"]]}},
 "Jinx": {"d": "When you roll a 1 on a D20 Test, a creature within 60 feet has Disadvantage on its next D20 Test. An enemy's natural 13 against you or your spell save becomes a 1.",
   "full": "**Mutual Misery.** When you roll a 1 on the d20 for a D20 Test, pick a creature you can see within 60 feet. For the next minute, it has Disadvantage on the next D20 Test it makes.\n**Unlucky Number.** When an enemy rolls a 13 on the d20 for an attack against you, or for a saving throw against a spell you cast, the roll counts as a 1."},
 "Lakshay: Oni": {"d": "Faction feat. Advantage on Piloting a Battleframe and on Intimidation and Persuasion with those who know your rank. Add Proficiency Bonus to a damage roll, save or AC once per turn.", "pre": "Battleframe Dragoon feat, 100 confirmed kills",
   "full": "Joining Lakshay normally grants the Ship feat Battleframe Dragoon in place of a Faction feat. You earn the rank of Oni only after proving yourself as a Dragoon.\n**Battleframe Expertise.** You have Advantage on Dexterity (Piloting) checks made while piloting a Battleframe.\n**Fearsome Reputation.** When you take the Influence action against a creature that knows your rank of Oni, you have Advantage on Charisma (Intimidation and Persuasion) checks.\n**Oni's Skill.** You can add your Proficiency Bonus to one damage roll or saving throw you make, or to your AC against one attack that hits you, which may turn the hit into a miss. After you do this, you cannot do it again until the start of your next turn."},
 "Laser Swordsmaster": {"d": "Crits with laser blades add maximum damage instead of doubling dice. Reaction: add Proficiency Bonus to AC against a blaster hit and maybe deflect it.", "pre": "Level 4+, Str 13+ and Dex 13+", "asi": ["STR", "DEX"],
   "full": "Raise Strength or Dexterity by 1, to a maximum of 20.\n**Cauterizing Critical.** When you score a Critical Hit with an Antimatter Dagger, Laser Claws, Laser Sword or Laser Greatsword, you slash through the target. Instead of rolling the damage dice twice, you add the maximum damage of the attack to the roll.\n**Deflect Blaster.** While you hold one of those four weapons and a creature hits you with a ranged blaster attack, you can use your Reaction to add your Proficiency Bonus to your AC against that attack. If that makes it miss, you can bounce the bolt at a creature you can see within 60 feet. The target must succeed on a Dexterity saving throw (DC 8 plus your Proficiency Bonus plus the modifier of the ability this feat raised) or take the damage the triggering attack would have dealt.",
   "act": "reaction"},
 "Latent Psionics": {"d": "Empathy as a Magic action. Psionic Blast deals an extra 1d10 Psychic damage. Mage Hand cantrip with an Invisible hand.", "pre": "Wrothian",
   "full": "**Empathy.** As a Magic action, you can probe the mind of a creature you can see within 30 feet and learn its emotional state.\n**Improved Psionic Blast.** Your Psionic Blast deals an extra 1d10 Psychic damage.\n**Minor Kinesis.** You learn the Mage Hand cantrip, and the hand is Invisible when you cast it this way. Intelligence, Wisdom or Charisma is your spellcasting ability for it (choose when you take this feat).",
   "dm": {"can": ["Mage Hand"]}},
 "Leviathan Suit": {"d": "Integrate one weapon, or two without the Two-Handed property, into your Aqua Suit. Blindsight 10 feet in the suit, 30 feet underwater.", "pre": "Nautilid",
   "full": "**Integrated Weapons.** You can build one weapon into your Aqua Suit, or two weapons (one in each arm) if neither has the Two-Handed property. A weapon you draw from the suit snaps into your hand and you cannot be disarmed of it. You can change which weapons are integrated when you finish a Long Rest.\n**Sonar.** While you wear your Aqua Suit, you have Blindsight out to 10 feet, or 30 feet when you are underwater.",
   "fx": {"senses": [["Blindsight", 10, "Leviathan Suit", "30 feet underwater, only while wearing your Aqua Suit"]]}},
 "Lilliputian": {"d": "Your size is Tiny. Your weapon damage dice drop one step. Opportunity Attacks against you have Disadvantage.", "pre": "Halfling",
   "full": "You belong to a rare line of halflings who are as small next to normal halflings as those are next to humans.\n**Tiny.** Your size is Tiny.\n**Miniature Weapons.** You can only wield weapons made for your size. They match the standard versions but their damage dice drop one step (d12 or 2d6 becomes d10, then d8, then d6, then d4, with d4 as the minimum).\n**Nimble.** Opportunity Attacks have Disadvantage against you.",
   "fx": {"notes": [["Note", "Lilliputian: size is Tiny, weapon damage dice drop one step, Opportunity Attacks against you have Disadvantage"]]}},
 "Magitechnician": {"d": "Your magic items use a better save DC when higher. Recharge one item on a Short Rest as if dawn had come, once per Long Rest.", "pre": "Level 4+", "asi": ["INT", "WIS", "CHA"],
   "full": "Raise Intelligence, Wisdom or Charisma by 1, to a maximum of 20.\n**Magic Item Expert.** If one of your magic items calls for a saving throw, it uses this DC when it is higher: 8 plus the modifier of the ability this feat raised plus your Proficiency Bonus.\n**Magic Item Recharge.** When you finish a Short Rest, you can make one magic item that regains charges or properties recharge as if the next dawn had come. After you do this, finish a Long Rest to do it again.",
   "lu": {"n": "Magic Item Recharge", "max": 1, "reset": "long", "tag": "Short Rest"}},
 "Marksman's Luck": {"d": "Once per turn flip one damage die on a Ranged weapon hit (not a d4). A ranged Critical Hit sets the target's Speed to 0 until the end of its next turn.", "pre": "Level 4+, Dex 13+", "asi": ["DEX"],
   "full": "Raise Dexterity by 1, to a maximum of 20.\n**Flip Die.** Once per turn, when you roll damage with a Ranged weapon, you can turn one of the damage dice over and use the number on its underside. This does not work on d4s. On a balanced die, the top and bottom numbers add up to one more than the highest face.\n**Enhanced Critical.** When you score a Critical Hit with a Ranged weapon, the target's Speed is 0 until the end of its next turn."},
 "Mechanic": {"d": "Technology proficiency (Expertise if you have it). Overheat on any blaster with extra damage of twice Proficiency Bonus. Mending, and Greater Mending once per Long Rest.", "pre": "Level 4+, Int 13+", "asi": ["INT"],
   "full": "Raise Intelligence by 1, to a maximum of 20.\n**Burn Out.** You can use the Overheat mastery property on any blaster, even without Weapon Mastery, and it does not count against your mastery weapon limit. When you use it through this feat, the extra damage equals twice your Proficiency Bonus and the weapon stays Overheated until you finish a Short Rest or Long Rest.\n**Technology Expert.** You gain proficiency in Technology. If you already have it, you gain Expertise in it instead.\n**Vent Tape Repairs.** You can cast Mending by using up a negligible amount of Vent Tape. By using up a whole roll of Vent Tape, you can cast Greater Mending once with no spell slot. Intelligence is your spellcasting ability for these spells. After you cast Greater Mending this way, finish a Long Rest to do so again.",
   "fx": {"skills": ["Technology"]}, "lu": {"n": "Greater Mending (Vent Tape)", "max": 1, "reset": "long", "tag": "Full roll of Vent Tape"},
   "dm": {"can": ["Mending"], "free": [[1, "Greater Mending"]], "ab": "INT"}},
 "Merc": {"d": "Swap a blaster's mastery for Bludgeon. Heavy or Two-Handed ranged hits within 10 feet add Proficiency Bonus damage. Learn Common Sign Language.", "pre": "Level 4+, Str 13+ and Dex 13+", "asi": ["STR", "DEX"],
   "full": "Raise Strength or Dexterity by 1, to a maximum of 20.\n**Blaster Melee.** When you attack with a blaster, you can swap its mastery property for Bludgeon on that attack. You can use Bludgeon with the blaster even without Weapon Mastery, and it does not count against your mastery weapon limit.\n**Point Blank.** When you hit a creature within 10 feet with a ranged attack using a weapon with the Heavy or Two-Handed property, the target takes extra damage equal to your Proficiency Bonus, of the same type the weapon deals.\n**Tactical Signals.** You learn Common Sign Language. You can send a tactical message of 10 words or fewer to a creature that can see you signal. It need not share a language with you, but it must understand at least one language.",
   "fx": {"langs": ["Common Sign Language"]}},
 "Metabolistic Magic": {"d": "After failing a D20 Test, spend a spell slot to add 2 plus its level. On a Short Rest spend Hit Dice to regain slots, once per Long Rest.", "pre": "Level 4+, Spellcasting", "asi": ["INT", "WIS", "CHA"],
   "full": "Raise Intelligence, Wisdom or Charisma by 1, to a maximum of 20.\n**Arcane Skill.** When you fail a D20 Test, you can spend a spell slot to add a bonus to the roll, which can turn it into a success. The bonus is 2 plus the level of the slot.\n**Vital Fuel.** When you finish a Short Rest, you can spend Hit Point Dice up to your Proficiency Bonus to regain spell slots. Choose slots whose combined level is no more than the number of Hit Dice spent. After you use this, finish a Long Rest to do so again.",
   "lu": {"n": "Vital Fuel", "max": 1, "reset": "long", "tag": "Short Rest"}},
 "Multiscale": {"d": "Pick a second Draconic Ancestry. Resistance to both damage types and either one for your Breath Weapon. Breath Weapon deals an extra 1d10.", "pre": "Dragonborn",
   "full": "**Dual Ancestry.** Pick a second Draconic Ancestry option. Your scales show both dragon ancestors. You have Resistance to the damage type of each ancestry and can use either type for your Breath Weapon.\n**Improved Breath Weapon.** Your Breath Weapon deals an extra 1d10 damage of the type set by your Draconic Ancestry."},
 "Night Blessed": {"d": "Stealth proficiency. Reaction to Hide when found, once per Rest. Reaction to move 5 feet without Opportunity Attacks when an enemy misses you in melee.", "pre": "Avia-Ra",
   "full": "You were born in tune with shadow rather than the sun.\n**Covert.** When you are hidden and a creature finds you with a successful Wisdom (Perception) check, you can use your Reaction to take the Hide action. If your Dexterity (Stealth) roll beats that Perception check, you slip to a new spot unseen and the creature does not notice you. After you use this, finish a Short Rest or Long Rest to do so again.\n**Craven.** When an enemy you can see misses you with a Melee attack, you can use your Reaction to move 5 feet without provoking Opportunity Attacks.\n**Stealthy.** You gain proficiency in Stealth.",
   "fx": {"skills": ["Stealth"]}, "lu": {"n": "Covert", "max": 1, "reset": "short", "tag": "Reaction"}, "act": "reaction"},
 "Porterling": {"d": "Advantage to escape grapples and nonmagical restraints. Move through the space of larger creatures. Add a d8 to High and Long jumps.", "pre": "Near-Human",
   "full": "You have a human parent and a gnome or halfling parent. You stand about as tall as a dwarf but are leaner, and you cannot grow a thick beard.\n**Flexible.** You have Advantage on checks to end the Grappled condition or to escape nonmagical restraints.\n**Nimbleness.** You can move through the space of any creature one size larger than you, but you cannot stop there.\n**Springheel Leap.** When you make a High Jump or Long Jump, you can roll a d8 and add the result in feet to the distance, even on a standing jump. Each foot still costs a foot of movement."},
 "Precognitive": {"d": "Augury always prepared and free once per Long Rest. At the start of your turn, record a d20 to swap in for any D20 Test, Proficiency Bonus times per Long Rest.", "pre": "Level 4+", "asi": ["INT", "WIS", "CHA"],
   "full": "Raise Intelligence, Wisdom or Charisma by 1, to a maximum of 20.\n**Augury.** You always have Augury prepared. You can cast it with no spell slot and no components, and then you need a Long Rest before casting it that way again. You can also cast it with spell slots. Your spellcasting ability for it is the ability this feat raised.\n**Impressions of the Future.** At the start of your turn, you can roll a d20 and record the number. Before the start of your next turn, you can use it in place of the roll of any D20 Test made by you or by a creature you can see. You can use this a number of times equal to your Proficiency Bonus and regain all uses on a Long Rest.",
   "lu": {"n": "Impressions of the Future", "max": "pb", "reset": "long", "tag": "Start of turn"},
   "dm": {"free": [[1, "Augury"]], "ab": "asi"}},
 "Proto-Man": {"d": "Advantage on saves against the Frightened condition. Hit Point maximum rises by 1, and by 1 again each level.", "pre": "Near-Human",
   "full": "You come from a world of ancient animals and huge plants. Your people are tough and sturdy, much like early humans.\n**Brave.** You have Advantage on saving throws to avoid or end the Frightened condition.\n**Primal Toughness.** Your Hit Point maximum increases by 1, and it increases by 1 again each time you gain a level.",
   "fx": {"notes": [["Advantage", "Saves to avoid or end Frightened (Brave)"]]}},
 "Psionic-Awakened": {"d": "Empathy as a Magic action. Mage Hand with extra range, Invisible hand and no V or S components. Unseen Servant at level 3 and Levitate at level 5, each free once per Long Rest.", "pre": "Near-Human",
   "full": "Most humans hold a faint psionic potential. You have unlocked yours, which may show as stark white hair, glowing pupils, or hair and clothes that drift about you.\n**Empathy.** As a Magic action, you can probe the mind of a creature you can see within 30 feet and learn its emotional state.\n**Psionics.** You learn the Mage Hand cantrip. You can cast it without Verbal or Somatic components, make the hand Invisible, and its range increases by 30 feet. At character level 3 you learn Unseen Servant, and at character level 5 you learn Levitate. You always have them prepared. You can cast each once without a spell slot and regain that ability when you finish a Long Rest. You can also cast them with spell slots. Intelligence, Wisdom or Charisma is your spellcasting ability for them (choose when you take this feat).",
   "dm": {"can": ["Mage Hand"], "free": [[3, "Unseen Servant"], [5, "Levitate"]]}},
 "Pyromaniac": {"d": "Fire Bolt. Burning Hands and Scorching Ray prepared, each free once per Long Rest. Reroll maximum Fire damage dice up to your Proficiency Bonus.", "pre": "Level 4+", "asi": ["INT", "WIS", "CHA"],
   "full": "Raise Intelligence, Wisdom or Charisma by 1, to a maximum of 20.\n**Firestarter Magic.** You know Fire Bolt and always have Burning Hands and Scorching Ray prepared. You can cast each of those two spells once without a slot, and need a Long Rest to do so again. You can also cast them with slots. The spellcasting ability is the one this feat raised.\n**Flare Damage.** When you deal Fire damage and roll the highest number on a damage die, you can roll that die again and add it, and keep rolling while you get the highest number. You can add at most a number of dice equal to your Proficiency Bonus (minimum 1).",
   "dm": {"can": ["Fire Bolt"], "free": [[1, "Burning Hands"], [1, "Scorching Ray"]], "ab": "asi"}},
 "Reanimated": {"d": "You are Undead. No Exhaustion from lacking food, drink or air. Scare a creature within 30 feet at Initiative. Resistance to Necrotic damage.", "pre": "Near-Human",
   "full": "You hover between death and life. You might be a classic undead such as a revenant, or the product of reckless science or a magical accident.\n**Creature Type.** You are Undead.\n**Deathless Body.** Going without food, drink or air does not give you levels of Exhaustion.\n**Scare.** When you roll Initiative, you can pick a creature you can see within 30 feet. It must succeed on a Wisdom saving throw (DC 8 plus your Charisma modifier plus your Proficiency Bonus) or have the Frightened condition until the end of its turn.\n**Undead Resistances.** You have Resistance to Necrotic damage.",
   "fx": {"res": ["Necrotic"]}},
 "Reptiloid": {"d": "Acid Spit replaces an attack: 60 feet, 1d10 Acid, scaling at levels 5, 11 and 17. Resistance to Acid, Fire or Poison.", "pre": "Near-Human",
   "full": "You have scaly, rough skin, slit eyes and a forked tongue.\n**Acid Spit.** When you take the Attack action, you can replace one attack with a spat glob of acid. It is a ranged attack with a range of 60 feet, you are proficient with it, and you add your Dexterity modifier to its attack and damage rolls. On a hit the target takes 1d10 Acid damage. This becomes 2d10 at character level 5, 3d10 at level 11 and 4d10 at level 17. You can use it a number of times equal to your Proficiency Bonus and regain all uses on a Long Rest.\n**Reptilian Resistance.** You have Resistance to Acid, Fire or Poison damage (choose when you take this feat).",
   "lu": {"n": "Acid Spit", "max": "pb", "reset": "long", "tag": "Replaces an attack"}},
 "Roguean": {"d": "Darkvision 60 feet. Resistance to Cold damage. No damage from cold Extreme Temperatures.", "pre": "Near-Human",
   "full": "You come from an icy, barren world flung away from its sun by some disaster. Surviving there gave you these traits.\n**Darkvision.** You have Darkvision out to 60 feet.\n**Cold Resistance.** You have Resistance to Cold damage.\n**Extremophile.** You take no damage from cold Extreme Temperatures. Extreme heat affects you as normal.",
   "fx": {"res": ["Cold"], "senses": [["Darkvision", 60, ""]]}},
 "S.S. St. Vincent: Archon": {"d": "Faction feat. Medicine proficiency and Spare the Dying as a Bonus Action. Reaction: Advantage on D20 Tests after an enemy Bloodies you or an ally, once per Long Rest.",
   "full": "You stand as a beacon of law and order on the Frontier.\n**First Aid.** You gain proficiency in Medicine. You also learn the Spare the Dying cantrip and can cast it as a Bonus Action.\n**White Angel's Vengeance.** When an enemy you can see within 60 feet deals damage that makes you or an ally you can see within 60 feet Bloodied, you can use your Reaction to gain Advantage on D20 Tests until the end of your next turn. After you use this, finish a Long Rest to do so again.",
   "fx": {"skills": ["Medicine"]}, "lu": {"n": "White Angel's Vengeance", "max": 1, "reset": "long", "tag": "Reaction"}, "act": "reaction",
   "dm": {"can": ["Spare the Dying"]}},
 "Scale and Fang: Scaleguard": {"d": "Faction feat. Bonus Action: an ally within 5 feet uses your AC if it is higher, until your next turn. Don or doff a Shield as a Bonus Action.",
   "full": "As a bodyguard of Scale & Fang, your duty is to protect your charge at any cost.\n**Block.** As a Bonus Action, pick an ally you can see. Until the start of your next turn, while that ally is within 5 feet of you, its AC equals your AC if yours is higher. The effect ends early if you or the ally become Incapacitated.\n**Quick Shield.** You can don or doff a Shield as a Bonus Action.",
   "act": "bonus"},
 "Sepulcher Knight: Deputy": {"d": "Faction feat. A badge that sways attitudes, Manacles as a Bonus Action, and a service Repeater you are proficient with, including its mastery.",
   "full": "You have been sworn in as a deputy or trainee of a Knight's Precinct, which gives you a badge and a gun.\n**Badge.** You can show your badge on your turn with no action. Creatures that see it treat you as they would the Sepulcher Knights. Law-abiding citizens are often Friendly and criminals are often Hostile.\n**Cuffs.** You can use Manacles as a Bonus Action.\n**Gun.** You are issued a Repeater as your service weapon. You are proficient with it and can use its mastery property even without Weapon Mastery, and it does not count against your mastery weapon limit.",
   "act": "bonus"},
 "Shapeshifter": {"d": "Spend 1 minute to change your appearance to anything of your size and basic shape, including another species. Your statistics stay the same.", "pre": "Amoeboid",
   "full": "Using your Biomimicry trait over 1 minute, you can fully reshape your look. You choose height, weight, facial features, voice, hair length, coloring and other details. You can pass as a member of another species, though none of your statistics change. You cannot look like a creature of a different size, and your basic shape stays the same."},
 "Shock Trooper": {"d": "When you roll Initiative without Disadvantage, draw a weapon and attack. Your Speed doubles in the first round of combat.", "pre": "Level 4+, Str 13+ and Dex 13+", "asi": ["STR", "DEX"],
   "full": "Raise Strength or Dexterity by 1, to a maximum of 20.\n**First Strike.** When you roll Initiative and do not have Disadvantage on the roll, you can draw a weapon and make an attack with it.\n**Rapid Advance.** In the first round of each combat, your Speed is doubled.",
   "fx": {"notes": [["Note", "Shock Trooper: first combat round Speed is doubled. On Initiative you can draw a weapon and attack"]]}},
 "Showman": {"d": "Performance proficiency (Expertise if you have it). Bonus Action taunt: Disadvantage on a creature's next attack against others. Proficiency Bonus times per Long Rest.", "pre": "Level 4+, Cha 13+", "asi": ["CHA"],
   "full": "Raise Charisma by 1, to a maximum of 20.\n**Expert Performer.** You gain proficiency in Performance. If you already have it, you gain Expertise in it instead.\n**Taunt.** As a Bonus Action you can mock a creature within 15 feet. If it can hear you (it need not understand), it has Disadvantage on the next attack roll it makes against a creature other than you before the end of its next turn. You can do this a number of times equal to your Proficiency Bonus and regain all uses on a Long Rest.",
   "fx": {"skills": ["Performance"]}, "lu": {"n": "Taunt", "max": "pb", "reset": "long", "tag": "Bonus Action"}, "act": "bonus"},
 "Silver-Tongued": {"d": "Use Int, Wis or Cha for Persuasion. Influence can raise a Hostile creature to Indifferent or an Indifferent one to Friendly. Learn three languages.",
   "full": "**Argumentative.** You can use Intelligence, Wisdom or Charisma for Persuasion checks.\n**Diplomatic.** When you take the Influence action, you can treat a Hostile creature as Indifferent, or an Indifferent creature as Friendly.\n**Polyglot.** You learn three languages of your choice."},
 "Simian": {"d": "Climb Speed equal to your Speed. A prehensile tail that holds objects but cannot attack. Reaction to cut fall damage by five times Proficiency Bonus.", "pre": "Near-Human",
   "full": "Your people evolved along a different path from High Terra and look like monkeys or apes. You are as clever as anyone else, you just like bananas a bit more.\n**Climbing Speed.** You have a Climb Speed equal to your Speed.\n**Prehensile Tail.** You can hold and use objects and weapons with your hands, feet and tail, but you cannot make attacks with a weapon held by your tail.\n**Soft Landing.** When you fall, you can use your Reaction to reduce the fall damage by five times your Proficiency Bonus.",
   "fx": {"notes": [["Speed", "Climb Speed equal to your Speed (Simian)"]]}, "act": "reaction"},
 "Technical": {"d": "Build a device that casts a non-damaging Wizard cantrip, changeable each Long Rest. Use Intelligence for one skill's checks and swap the skill each level.",
   "full": "**Cantrip Device.** You build a device that lets you cast one cantrip of your choice from the Wizard list that deals no damage (choose when you build it). When you finish a Long Rest, you can build a new device with a different cantrip, and the old one stops working. Intelligence, Wisdom or Charisma is your spellcasting ability for it (choose when you take this feat).\n**Mind Over Matter.** Pick one skill. When you make an ability check with that skill, you can use your Intelligence modifier in place of the normal ability modifier. Each time you gain a level, you swap that skill for a different one."},
 "Technopath": {"d": "Technomancy cantrip. Technical Difficulties at level 3 and Circuit Breaker at level 5, each free once per Long Rest.", "pre": "Gnome",
   "full": "You know the Technomancy cantrip. At character level 3 you learn Technical Difficulties, and at character level 5 you learn Circuit Breaker. You always have these spells prepared. You can cast each once without a spell slot and regain that ability when you finish a Long Rest. You can also cast them with spell slots. Intelligence, Wisdom or Charisma is your spellcasting ability for them (choose when you take this feat).",
   "dm": {"can": ["Technomancy"], "free": [[3, "Technical Difficulties"], [5, "Circuit Breaker"]]}},
 "The Cabal: Soul Broker": {"d": "Faction feat. Gain Soul Credits equal to the CR of enemies you kill (10 credits trade for 100 CR). Advantage on Influence against Hostile creatures, once per Rest.",
   "full": "You have passed the legal and ritual exams to become a bonded soul broker for the Cabal.\n**Soul Dividends.** You are paid for sending souls onward. When you kill an enemy, you gain 1 Soul Credit for each point of its Challenge Rating, rounded down (minimum 0). You can trade 10 Soul Credits for 100 CR.\n**Moral Relativism.** When you make an Influence check against a Hostile creature, you can have Advantage on the roll instead of Disadvantage. After you use this, finish a Short Rest or Long Rest to do so again.",
   "lu": {"n": "Moral Relativism", "max": 1, "reset": "short", "tag": "Influence check"}},
 "The Coalition: Recruit": {"d": "Faction feat. Gain Athletics, Martial weapons, Light armor or Shield training. Reaction to move 15 feet after a Dexterity save against an area effect, once per Long Rest.",
   "full": "To join the Coalition you went through hard training or achieved a feat that stands for it.\n**Basic Training.** You gain one of these, your choice: proficiency in Athletics, proficiency with Martial weapons, training with Light armor, or training with Shields. If you already have all of them, you gain Weapon Mastery with the Repeater or Standard Carbine instead, and it does not count against your mastery weapon limit.\n**Dive for Cover.** When you make a Dexterity saving throw against an effect with an area, you can use your Reaction to move up to 15 feet without provoking Opportunity Attacks, which may take you out of the area. After you do this, finish a Long Rest to do so again.",
   "lu": {"n": "Dive for Cover", "max": 1, "reset": "long", "tag": "Reaction"}, "act": "reaction"},
 "The Firm: Contractor": {"d": "Faction feat. Simple weapons that deal 1d4 deal 2d4 instead. Expertise in one skill you know.",
   "full": "You are a licensed Contractor. The pen may beat the sword, but the dagger beats them both.\n**Backstabber.** When you hit a creature with a Simple weapon that deals 1d4 damage, it deals 2d4 damage instead.\n**Expertise.** You gain Expertise in one skill you are proficient in, your choice."},
 "The Tower: Agent": {"d": "Faction feat. Illusory Script free with Intelligence. Cast spells without V, S or non-costly M components, Proficiency Bonus times per Long Rest.", "pre": "Spellcasting",
   "full": "As a full Tower Agent you know the organization's secret ciphers and its quiet magical arts.\n**Mark of Induction.** You bear a tattoo that only other Tower Agents can see, marking your membership.\n**Mage Cypher.** You can cast Illusory Script without a spell slot or Material components. Intelligence is your spellcasting ability for it.\n**Subtle Spell.** When you cast a spell, you can cast it without Verbal, Somatic or Material components, except Material components the spell consumes or that have a stated cost. You can do this a number of times equal to your Proficiency Bonus and regain all uses on a Long Rest.",
   "lu": {"n": "Subtle Spell", "max": "pb", "reset": "long", "tag": "Cast without components"},
   "dm": {"can": ["Illusory Script"], "ab": "INT"}},
 "Two-Headed": {"d": "Advantage on Initiative once per Rest. Advantage on saves against Blinded, Charmed, Deafened and Frightened. You stay conscious during a Long Rest.", "pre": "Near-Human",
   "full": "Like an ettin, you have two heads with different personalities sharing one body.\n**Look Both Ways.** You can have Advantage when you roll Initiative. After you use this, finish a Short Rest or Long Rest to do so again.\n**Two Heads.** You have Advantage on saving throws to avoid or end these conditions: Blinded, Charmed, Deafened and Frightened.\n**Wakeful.** One head is always awake, so you stay conscious during a Long Rest.",
   "lu": {"n": "Look Both Ways", "max": 1, "reset": "short", "tag": "Initiative"},
   "fx": {"notes": [["Advantage", "Saves to avoid or end Blinded, Charmed, Deafened, Frightened (Two Heads)"]]}},
 "Upgraded": {"d": "Reconfigure Ability Scores as a Bonus Action, once per Long Rest. Magic action to swap Thermalsight for Blindsight 10 feet or Darkvision 120 feet.", "pre": "Vect",
   "full": "**Configuration Upgrade.** You can use your Reconfigurable Ability Scores as a Bonus Action, and you regain the ability to do so when you finish a Long Rest.\n**Improved Optics.** As a Magic action, you can swap your Thermalsight for Blindsight with a range of 10 feet or Darkvision with a range of 120 feet. The sense lasts until you use this feature again to go back to Thermalsight or pick a different one.",
   "act": "bonus"},
 "Versatile Passenger": {"d": "Ship feat. Help the Engineer (ship regains Shield Points equal to Proficiency Bonus), the Gunner (Advantage on attacks) or the Pilot (Advantage on the ship's saves).",
   "full": "You may have no fixed Crew Role, but you know how to be useful in a crisis.\n**Engineer Helper.** You can take the Help action to assist the Engineer. The ship regains Shield Points equal to your Proficiency Bonus, and other ships have Disadvantage on saving throws against this ship's systems until the start of your next turn.\n**Gunner Helper.** You can take the Help action to assist the Gunner. The Gunner has Advantage on attack rolls until the start of your next turn.\n**Pilot Helper.** You can take the Help action to assist the Pilot. The Pilot has Advantage on saving throws made on behalf of the ship until the start of your next turn."},
 "Warzone Nomad": {"d": "Dash as a Bonus Action and gain Temporary Hit Points equal to Proficiency Bonus. Drop to 1 Hit Point instead of 0 once per Long Rest.", "pre": "Orc",
   "full": "**Adrenaline Rush.** You can take the Dash action as a Bonus Action. When you do, you gain Temporary Hit Points equal to your Proficiency Bonus. You can do this a number of times equal to your Proficiency Bonus and regain all uses when you finish a Short Rest or Long Rest.\n**Relentless Endurance.** When you are reduced to 0 Hit Points but not killed outright, you can drop to 1 Hit Point instead. After you use this, finish a Long Rest to do so again.",
   "lu": {"n": "Adrenaline Rush", "max": "pb", "reset": "short", "tag": "Bonus Action"}, "act": "bonus"},
}
